<?php require_once '../includes/auth.php';require_once '../config/uploads.php';$slug=preg_replace('/[^a-z0-9-]/','',strtolower($_GET['slug']??''));$q=$pdo->prepare('SELECT s.* FROM stores s JOIN users u ON u.id=s.user_id WHERE s.slug=? AND u.account_status=?');$q->execute([$slug,'active']);$s=$q->fetch();if(!$s)exit('Store not found');$cat=trim($_GET['category']??'');$sql='SELECT p.* FROM products p WHERE p.store_id=? AND p.available=1 AND p.moderation_status=?';$a=[$s['id'],'approved'];if($cat){$sql.=' AND p.category=?';$a[]=$cat;}$q=$pdo->prepare($sql.' ORDER BY category,name');$q->execute($a);$ps=$q->fetchAll();$title=$s['name'];require '../includes/header.php';?><h1><?=e($s['name'])?></h1><p><?=e($s['description'])?></p><a class="btn btn-success mb-3" href="/public/cart.php?slug=<?=e($slug)?>">Cart (<?=cart_count()?>)</a><div class="row g-3"><?php foreach($ps as $p):?><div class="col-6 col-md-4"><div class="card h-100"><?php if($p['image']):?><img class="card-img-top" style="height:180px;object-fit:cover" src="<?=e($uploadUrl . '/' . $p['image'])?>" alt="<?=e($p['name'])?>"><?php endif;?><div class="card-body"><h5><?=e($p['name'])?></h5><p><?=e($p['category'])?> · <?=money($p['price'])?></p><a class="btn btn-success btn-sm" href="/public/product.php?id=<?=e($p['id'])?>&slug=<?=e($slug)?>">View</a></div></div></div><?php endforeach;?></div><?php require '../includes/footer.php';?>